SUITE_TEXT = __file__.rsplit("\\", 1)[0]
CLOSURE_TEXT = SUITE_TEXT + "\\closure_high_r2.json"

def _norm(value):
    return os.path.normcase(os.path.abspath(os.fsdecode(value)))

def _option(name):
    if sys.argv.count(name) != 1:
        raise RuntimeError("exactly one " + name + " required")
    return sys.argv[sys.argv.index(name) + 1]

_out_text = _option("--out")
_worker = "--worker" in sys.argv
_bootstrap = "--bootstrap-only" in sys.argv
_read_paths = set(BOOTSTRAP_CODE_READS) | {_norm(__file__), _norm(CLOSURE_TEXT)}
_write_names = ({"events.jsonl", "result.json", "junit.xml"} if _worker else
                {"command.json", "stdout.txt", "stderr.txt", "supervisor.json"})
_write_paths = {_norm(_out_text + "\\" + name) for name in _write_names}
_denials = []
_events = []
_event_stream = None
_spawn_command = None
_spawn_environment = None
_spawn_remaining = 0
_write_mask = os.O_WRONLY | os.O_RDWR | os.O_CREAT | os.O_TRUNC | os.O_APPEND

def _deny(event, path=None, mode=None, flags=None):
    row = {"event": event, "path": path, "mode": mode, "flags": flags}
    _denials.append(row)
    # This survives any deferred-import/bootstrap failure; no denied contents.
    sys.stderr.write("ORIGIN_EFFECT_DENIED " + repr(row) + "\n")
    if _event_stream is not None:
        _event_stream.write(repr(row) + "\n")
        _event_stream.flush()
    raise RuntimeError("origin-test effect denied: " + event)

def _source_code(loader, fullname):
    # get_code's normal pyc probe is deliberately bypassed for EVERY source import.
    raw = loader.get_data(loader.path)
    return loader.source_to_code(raw, loader.path)

def _no_sourceless(loader, fullname):
    _deny("sourceless-import", loader.path)

_external.SourceFileLoader.get_code = _source_code
_external.SourcelessFileLoader.get_code = _no_sourceless

def _audit(event, values):
    global _spawn_remaining
    if event.startswith(("socket.", "ctypes.", "winreg.")) or event in {
        "os.system", "os.symlink", "os.link", "os.remove", "os.rmdir", "os.rename",
        "shutil.rmtree", "os.fork", "os.forkpty", "os.posix_spawn", "os.spawn",
        "os.exec", "os.chmod", "os.chown", "os.utime", "os.truncate",
        "os.putenv", "os.unsetenv", "os.startfile", "os.kill", "os.killpg",
        "os.setxattr", "os.removexattr", "shutil.copyfile", "shutil.copymode",
        "shutil.copystat", "os.chdir", "os.add_dll_directory", "winapi.CreateJunction"}:
        _deny(event)
    if event == "subprocess.Popen":
        exe, argv, cwd, env = values
        if (_worker or _spawn_remaining != 1 or argv != _spawn_command or
            _norm(exe) != _norm(sys.executable) or _norm(cwd) != _norm(_out_text) or
            env != _spawn_environment):
            _deny(event)
        _spawn_remaining = 0
    if event == "open":
        if not isinstance(values[0], (str, bytes, os.PathLike)):
            _deny(event, "non-path descriptor", values[1], values[2])
        text = os.fsdecode(values[0])
        path = _norm(text)
        parts = path.replace("/", "\\").split("\\")
        if (path.endswith((".pyc", ".pyo", ".pth")) or any(
            p.startswith((".env", ".credentials")) or p in {
                "auth.json", "id_rsa", "id_ed25519", "credentials", "credentials.json"}
            for p in parts)):
            _deny(event, text, values[1], values[2])
        flags = values[2]
        write = isinstance(flags, int) and bool(flags & _write_mask)
        if path not in (_write_paths if write else _read_paths):
            _deny(event, text, values[1], flags)
        _events.append({"event": "open", "path": text, "write": bool(write)})
